// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

/**
 * Unit spec for {@link LmdbNativeStrategyArbiter}: how a winner is chosen among candidate strategies, and what happens
 * when the cost model cannot tell them apart.
 * <p>
 * The behaviour under test replaces a set of {@code if} ladders whose outcome was decided by the physical order of the
 * branches. The two properties that make the replacement worth having are pinned here: selection depends only on the
 * candidate <em>set</em> (see {@link #selectionIsInvariantUnderPermutation()}), and an uncertain cost model changes
 * nothing rather than changing everything.
 */
public class LmdbNativeStrategyArbiterTest {

	/**
	 * These cases pin the ranking RULE, so they must not inherit what other queries in the same JVM taught the runtime
	 * calibrator — with learned factors in play, a measured speed difference legitimately overrules a specialization
	 * tie-break, which would make these assertions depend on test execution order.
	 */
	@org.junit.jupiter.api.BeforeEach
	public void isolateFromLearnedCalibration() {
		LmdbNativeCostCalibration.reset();
	}

	@org.junit.jupiter.api.AfterEach
	public void clearCalibrationState() {
		LmdbNativeCostCalibration.reset();
		System.clearProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY);
	}

	private static void measure(String tag, double nanosPerUnit, int times) {
		for (int i = 0; i < times; i++) {
			LmdbNativeCostCalibration.record(tag, 10_000d, (long) (nanosPerUnit * 10_000d));
		}
	}

	private static LmdbNativeStrategyProposal<String> proposal(String tag, LmdbNativeWork work) {
		return new LmdbNativeStrategyProposal<>(() -> tag, work, tag, () -> {
		});
	}

	private static LmdbNativeStrategyProposal<String> proposal(String tag, double cost) {
		return proposal(tag, LmdbNativeWork.exact(cost));
	}

	private static String winner(List<LmdbNativeStrategyProposal<String>> candidates) {
		int index = LmdbNativeStrategyArbiter.rank(candidates);
		return index < 0 ? null : candidates.get(index).tag;
	}

	// ---------------------------------------------------------------- cost decides

	@Test
	public void strictDominationDecides() {
		List<LmdbNativeStrategyProposal<String>> candidates = List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_IR_KERNEL, LmdbNativeWork.between(1D, 10D)),
				proposal(LmdbNativeAttemptMetrics.PATH_BATCH, LmdbNativeWork.between(100D, 200D)));

		assertThat(winner(candidates))
				.as("a candidate whose whole interval is below every rival's wins on cost, even though the "
						+ "specialization order would have preferred the other one")
				.isEqualTo(LmdbNativeAttemptMetrics.PATH_IR_KERNEL);
	}

	@Test
	public void overlappingIntervalsFallBackToSpecializationOrder() {
		List<LmdbNativeStrategyProposal<String>> candidates = List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_IR_KERNEL, LmdbNativeWork.between(10D, 200D)),
				proposal(LmdbNativeAttemptMetrics.PATH_WCOJ, LmdbNativeWork.between(50D, 300D)));

		assertThat(winner(candidates))
				.as("the kernel's interval is not strictly below WCOJ's, so cost has not earned the decision and "
						+ "the row-count reducer keeps it -- this is exactly the HIGHLY_CONNECTED q8 shape")
				.isEqualTo(LmdbNativeAttemptMetrics.PATH_WCOJ);
	}

	@Test
	public void unknownCostNeitherWinsNorLoses() {
		List<LmdbNativeStrategyProposal<String>> candidates = List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_IR_KERNEL, LmdbNativeWork.UNKNOWN),
				proposal(LmdbNativeAttemptMetrics.PATH_BATCH, LmdbNativeWork.UNKNOWN));

		assertThat(winner(candidates))
				.as("with nothing priced, the specialization order alone decides")
				.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
	}

	@Test
	public void aPricedCandidateCannotDisplaceAnUnpricedOneOnCost() {
		List<LmdbNativeStrategyProposal<String>> candidates = List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_IR_KERNEL, LmdbNativeWork.exact(1D)),
				proposal(LmdbNativeAttemptMetrics.PATH_WCOJ, LmdbNativeWork.UNKNOWN));

		assertThat(winner(candidates))
				.as("an unknown rival could be cheaper for all we know, so a cheap-looking candidate has not "
						+ "dominated anything and the specialization order still decides")
				.isEqualTo(LmdbNativeAttemptMetrics.PATH_WCOJ);
	}

	// ---------------------------------------------------------------- order independence

	@Test
	public void selectionIsInvariantUnderPermutation() {
		List<LmdbNativeStrategyProposal<String>> base = new ArrayList<>(List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_IR_KERNEL, LmdbNativeWork.between(10D, 200D)),
				proposal(LmdbNativeAttemptMetrics.PATH_WCOJ, LmdbNativeWork.between(50D, 300D)),
				proposal(LmdbNativeAttemptMetrics.PATH_BATCH, LmdbNativeWork.between(20D, 400D)),
				proposal(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP, LmdbNativeWork.UNKNOWN)));

		String expected = winner(base);
		// Every rotation is a different declaration order for the same candidate set.
		for (int shift = 1; shift < base.size(); shift++) {
			List<LmdbNativeStrategyProposal<String>> rotated = new ArrayList<>(base);
			Collections.rotate(rotated, shift);
			assertThat(winner(rotated))
					.as("the winner must be a function of the candidate set, not of the order they were offered; "
							+ "this is the property an if/else ladder cannot have")
					.isEqualTo(expected);
		}
	}

	@Test
	public void tieBreaksMatchTheLadderTheyReplace() {
		// chooseTag kept the sequential strategy when costs were equal; the preference table must agree.
		assertThat(winner(List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 100D),
				proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 100D))))
						.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		assertThat(winner(List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_AGGREGATION, 100D),
				proposal(LmdbNativeAttemptMetrics.PATH_FACTORIZED_TAIL, 100D))))
						.isEqualTo(LmdbNativeAttemptMetrics.PATH_FACTORIZED_TAIL);
	}

	@Test
	public void cheaperParallelStillWinsWhenItActuallyDominates() {
		assertThat(winner(List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 10D),
				proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 100D))))
						.isEqualTo(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES);
	}

	// ---------------------------------------------------------------- exploration

	@Test
	public void aNeverMeasuredRivalIsExploredOnceTheIncumbentHasEvidence() throws IOException {
		// The incumbent is measured at ~1ns/unit, so its time interval overlaps the rival's raw work interval and
		// cost decides nothing; the ladder would keep batch forever, so the rival could never earn a measurement.
		// At zero observations the exploration probability is exactly 1, which makes this test deterministic.
		measure(LmdbNativeAttemptMetrics.PATH_BATCH, 1d, 200);

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000d));

			assertThat(arbiter.select())
					.as("a strategy that never wins never gets measured and so can never win; exploration must "
							+ "break that deadlock by running the unmeasured rival")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES);
		}
	}

	@Test
	public void coldStartNeverExplores() throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000d));

			assertThat(arbiter.select())
					.as("before anything is measured the first execution is the measurement; dispatch must be "
							+ "exactly the ladder")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void aRivalAlreadyKnownToBeFarWorseIsNeverExplored() throws IOException {
		measure(LmdbNativeAttemptMetrics.PATH_BATCH, 1d, 200);

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			// Unmeasured, but its own work estimate already sits far above the incumbent's measured time.
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000_000d));

			assertThat(arbiter.select())
					.as("exploring a candidate already known to be far worse buys nothing worth its cost; the "
							+ "overlap requirement is what keeps exploration bounded")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void disablingExplorationRestoresTheLadder() throws IOException {
		System.setProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY, "false");
		measure(LmdbNativeAttemptMetrics.PATH_BATCH, 1d, 200);

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000d));

			assertThat(arbiter.select()).isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	// ---------------------------------------------------------------- lifecycle

	@Test
	public void losersAreReleasedExactlyOnceAndTheWinnerIsNotReleased() throws IOException {
		AtomicInteger winnerReleases = new AtomicInteger();
		AtomicInteger loserReleases = new AtomicInteger();

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "wcoj", LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_WCOJ, winnerReleases::incrementAndGet));
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "batch", LmdbNativeWork.exact(100D),
					LmdbNativeAttemptMetrics.PATH_BATCH, loserReleases::incrementAndGet));

			assertThat(arbiter.select()).isEqualTo("wcoj");
		}

		assertThat(winnerReleases).as("the winner's resources were handed to the caller, not released").hasValue(0);
		assertThat(loserReleases).as("the loser must give back the admission it reserved while being costed")
				.hasValue(1);
	}

	@Test
	public void bindTimeDeclineFallsThroughToTheNextBestCandidate() throws IOException {
		AtomicInteger declinedReleases = new AtomicInteger();

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			// The cheapest candidate cannot actually bind -- a compiled kernel whose compile is still pending, say.
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> null, LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_IR_KERNEL, declinedReleases::incrementAndGet));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 100D));

			assertThat(arbiter.select())
					.as("a strategy that declines at bind time must hand the plan to the next-best candidate, "
							+ "not fail the query")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void everyCandidateDecliningYieldsNoSelection() throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> null, LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_IR_KERNEL, () -> {
					}));
			assertThat(arbiter.select()).isNull();
		}
	}

	@Test
	public void aProposerReturningNullContributesNoCandidate() throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> null);
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 100D));

			assertThat(arbiter.candidateCount())
					.as("a strategy that cannot handle the plan is not a strategy that lost")
					.isEqualTo(1);
			assertThat(arbiter.select()).isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void closingWithoutSelectingReleasesEveryCandidate() {
		AtomicInteger releases = new AtomicInteger();
		LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null);
		try {
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "a", LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_WCOJ, releases::incrementAndGet));
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "b", LmdbNativeWork.exact(2D),
					LmdbNativeAttemptMetrics.PATH_BATCH, releases::incrementAndGet));
		} catch (IOException e) {
			throw new AssertionError(e);
		} finally {
			arbiter.close();
		}
		assertThat(releases).as("an abandoned arbitration must not leak reserved admission").hasValue(2);
	}

	// ---------------------------------------------------------------- preference table

	@Test
	public void rowCountReducersOutrankConstantFactorReducers() {
		assertThat(LmdbNativeStrategyPreference.prefers(LmdbNativeAttemptMetrics.PATH_WCOJ,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE)).isTrue();
		assertThat(LmdbNativeStrategyPreference.prefers(LmdbNativeAttemptMetrics.PATH_PREFIX_RUN_GROUPS,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE)).isTrue();
		assertThat(LmdbNativeStrategyPreference.prefers(LmdbNativeAttemptMetrics.PATH_BATCH,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL)).isTrue();
		assertThat(LmdbNativeStrategyPreference.prefers(LmdbNativeAttemptMetrics.PATH_IR_KERNEL,
				LmdbNativeAttemptMetrics.PATH_BATCH)).isFalse();
	}

	@Test
	public void parameterizedLabelsRankAsTheirBaseStrategy() {
		assertThat(LmdbNativeStrategyPreference.rank("factorizedRows(flatPrefix=1, prefix=chain)"))
				.isEqualTo(LmdbNativeStrategyPreference.rank(LmdbNativeAttemptMetrics.PATH_FACTORIZED_ROWS));
	}

	@Test
	public void unknownStrategiesRankLastAndCannotDisplaceDeclaredOnes() {
		assertThat(LmdbNativeStrategyPreference.rank("somethingNobodyDeclared")).isEqualTo(Integer.MAX_VALUE);
		assertThat(LmdbNativeStrategyPreference.prefers("somethingNobodyDeclared",
				LmdbNativeAttemptMetrics.PATH_NESTED_LOOP)).isFalse();
	}
}
